/**
 * Public Fixture API
 * 
 * This module is the public API for defining fixtures.
 * It's designed to be stable across versions - projects can use a different
 * @vscode/component-explorer version than the explorer viewer uses.
 * 
 * Use Symbol.for() instead of Symbol() so the same symbol is shared across
 * different versions of this package.
 *
 * @module fixtureApi
 */

import { z } from 'zod';

// ============================================================================
// Types for fixture definition (re-exported for convenience)
// ============================================================================

/**
 * Disposable resource that can be cleaned up.
 * `dispose` may be sync or async; the framework awaits the returned promise (if any)
 * and captures any thrown errors.
 */
export interface IDisposable {
  dispose(): void | Promise<void>;
}

export type DebugPanelPlacement = 'canvas-right' | 'bottom-panel';

export interface DebugPanelViewContext<TAction> {
  sendAction(action: TAction): void;
}

export interface DebugPanelViewInstance<TState> extends IDisposable {
  update(state: TState): void;
}

export interface DefineDebugPanelOptions<TState, TAction> {
  readonly id: string;
  readonly title: string;
  readonly placement?: DebugPanelPlacement;
  render(
    container: HTMLElement,
    context: DebugPanelViewContext<TAction>,
  ): DebugPanelViewInstance<TState>;
}

interface ErasedDebugPanelViewInstance extends IDisposable {
  update(state: unknown): void;
}

/**
 * A statically declared custom panel. `TState` is published by the fixture and
 * `TAction` is sent back by the panel UI.
 */
export interface DebugPanelDefinition<TState = unknown, TAction = unknown> {
  readonly id: string;
  readonly title: string;
  readonly placement?: DebugPanelPlacement;
  /** @internal Viewer-side, type-erased renderer produced by defineDebugPanel. */
  readonly _render: (
    container: HTMLElement,
    sendAction: (action: unknown) => void,
  ) => ErasedDebugPanelViewInstance;
  /** @internal Carries types for inference without affecting the runtime shape. */
  readonly _types?: { readonly state: TState; readonly action: TAction };
}

export interface DebugPanelChannel<TState, TAction> {
  publish(state: TState): void;
  onAction(listener: (action: TAction) => void): IDisposable;
}

export type DebugPanelActivation<TState, TAction> = (
  channel: DebugPanelChannel<TState, TAction>,
) => void | IDisposable;

export interface FixtureDebugApi {
  connect<TState, TAction>(
    panel: DebugPanelDefinition<TState, TAction>,
    activate: DebugPanelActivation<TState, TAction>,
  ): IDisposable;
}

export interface FixtureInputControlOptions {
  readonly placement?: 'sidebar' | 'toolbar' | 'both';
  readonly label?: string;
  readonly title?: string;
}

/** Brand for an output that can be observed and edited while its Output panel is visible. */
export const interactiveOutputBrand = Symbol.for('@vscode/component-explorer/interactiveOutput/v1');

export interface InteractiveOutput<T> {
  readonly [interactiveOutputBrand]: true;
  getSnapshot(): T;
  activate(channel: DebugPanelChannel<T, T>): void | IDisposable;
}

/**
 * Result of a render operation.
 * Supports both sync and async rendering with cancellation.
 * All fields are optional for simple use cases.
 */
export interface RenderResult {
  /**
   * Resolves when the component is fully rendered and ready.
   * For sync renders, this can be omitted (treated as immediately ready).
   * Rejects if the render is aborted via the AbortSignal.
   */
  readonly ready?: Promise<void>;

  /**
   * Cleanup function. Called when the fixture is unmounted.
   * May be sync or async; the framework awaits the returned promise (if any).
   * Errors thrown (sync or async) are captured and surfaced via the
   * `previousDispose` field of the next render report (or `currentDispose`
   * if `disposeAfter` was requested).
   * Can be omitted if no cleanup is needed.
   */
  dispose?(): void | Promise<void>;

  /**
   * Arbitrary data to include in the render report.
   * Visible to the CLI and MCP tools (surfaced as `output`).
   *
   * Symmetric counterpart of `RenderContext.input`: input flows in, output flows out.
   */
  readonly output?: unknown;
}

/**
 * What the render function can return.
 * - undefined: no cleanup needed, immediately ready
 * - RenderResult: object with optional ready/dispose
 * - Promise<...>: async render that resolves to undefined or RenderResult
 */
export type RenderReturn = RenderResult | undefined | void | Promise<RenderResult | undefined | void>;

/**
 * Context passed to the render function.
 *
 * @typeParam TInput - Shape of `input`, inferred from the fixture's zod `inputSchema`
 *   (defaults to `unknown` when no schema is declared).
 */
export interface RenderContext<TInput = unknown> {
  /**
   * Unique identifier of the fixture being rendered.
   * Stable across renders of the same fixture; useful for keying caches,
   * logging, or distinguishing between sibling fixtures sharing a render function.
   */
  readonly fixtureId: string;

  /** AbortSignal for cancellation; check signal.aborted or listen to 'abort' event */
  readonly signal: AbortSignal;

  /** Register a disposable to be cleaned up when the fixture is unmounted. Returns the same disposable for chaining. */
  addDisposable<T extends IDisposable>(disposable: T): T;

  /**
   * Observes one input property without remounting the fixture. The listener is
   * invoked immediately and again for subsequent changes to this property.
   * Input properties without a watcher retain the default remount behavior.
   */
  watchInput<TKey extends Extract<keyof TInput, string>>(
    key: TKey,
    listener: (value: TInput[TKey], input: TInput) => void,
  ): IDisposable;

  /** Connects statically declared debug panels to this live fixture instance. */
  readonly debug: FixtureDebugApi;

  /**
   * Describes where this fixture is being rendered. Use this to enable dev-only affordances
   * (e.g. extra controls, logging) without affecting screenshots or embedded views.
   */
  readonly host: RenderHost;

  /**
   * Data passed in by the caller (CLI/MCP screenshot tool, explorer UI). Use this to
   * parameterize the fixture: e.g. switch theme, vary props, select a scenario.
   *
   * When the fixture declares a zod `inputSchema`, this is typed as `z.infer<typeof schema>`
   * and populated with the schema's defaults for any keys the caller omitted. Without a
   * schema it is `unknown` (and `undefined` when no input was provided).
   *
   * Symmetric with `RenderResult.output` (which flows back out to the caller).
   */
  readonly input: TInput;
}

/**
 * Describes the environment a fixture is rendered in.
 */
export type RenderHost =
  /** Rendered in the Component Explorer UI (visible to a human). */
  | { readonly kind: 'explorer-ui'; readonly interactive: true }
  /** Headless render for CLI/MCP screenshots. */
  | { readonly kind: 'headless'; readonly interactive: false }
  /** Rendered inside an isolation iframe (user-facing standalone view). */
  | { readonly kind: 'embedded'; readonly interactive: false };

/**
 * Style definition for shadow DOM injection.
 */
export type StyleDefinition =
  | { readonly type: 'css'; readonly content: string }
  | { readonly type: 'url'; readonly href: string }
  | { readonly type: 'adopted'; readonly sheet: CSSStyleSheet };

/**
 * Display mode for a component.
 */
export type DisplayMode = PageMode | ComponentMode;

/**
 * Page mode - component fills a viewport with device presets.
 */
export interface PageMode {
  readonly type: 'page';
  readonly viewports: ViewportPreset[];
}

/**
 * Component mode - renders at natural size.
 */
export interface ComponentMode {
  readonly type: 'component';
}

/**
 * Viewport preset - either a named preset or custom dimensions.
 */
export type ViewportPreset =
  | ViewportPresetName
  | { readonly name: string; readonly width: number; readonly height: number };

export type ViewportPresetName = 'mobile' | 'tablet' | 'desktop';

// ============================================================================
// JSON Schema (subset, intentionally permissive)
// ============================================================================

/**
 * Minimal JSON Schema interface used to describe a fixture's expected `input` shape.
 *
 * This is the *derived* form: fixtures declare their input with a zod schema
 * (`DefineFixtureOptions.inputSchema`) and the framework converts it to this JSON Schema
 * at define time. Tools (CLI/MCP/explorer UI) read it for validation, autocompletion, or
 * to generate input-editing controls.
 *
 * Intentionally a structural, recursive type covering the subset of JSON Schema we
 * actually surface to tools — the index signature lets any additional standard JSON Schema
 * keywords (`format`, `pattern`, `oneOf`, `$ref`, …) flow through without changing this interface.
 */
export interface IJsonSchema {
  readonly type?: 'object' | 'array' | 'string' | 'number' | 'integer' | 'boolean' | 'null';
  readonly properties?: { readonly [key: string]: IJsonSchema };
  readonly required?: readonly string[];
  readonly items?: IJsonSchema;
  readonly enum?: readonly unknown[];
  readonly const?: unknown;
  readonly default?: unknown;
  readonly description?: string;
  readonly title?: string;
  readonly additionalProperties?: boolean | IJsonSchema;
  readonly anyOf?: readonly IJsonSchema[];
  readonly oneOf?: readonly IJsonSchema[];
  readonly allOf?: readonly IJsonSchema[];
  readonly [key: string]: unknown;
}

// ============================================================================
// Brand symbols - use Symbol.for() for cross-version compatibility
// ============================================================================

/** Brand symbol to identify single fixtures */
export const singleFixtureBrand = Symbol.for('@vscode/component-explorer/singleFixture/v1');

/** Brand symbol to identify fixture groups */
export const fixtureGroupBrand = Symbol.for('@vscode/component-explorer/fixtureGroup/v1');

/** Brand symbol to identify fixture variants */
export const fixtureVariantsBrand = Symbol.for('@vscode/component-explorer/fixtureVariants/v1');

// ============================================================================
// Define fixture options
// ============================================================================

/**
 * Options for defining a single component fixture.
 *
 * @typeParam TInput - Shape of the fixture's `input`, inferred from `inputSchema`.
 */
export interface DefineFixtureOptions<TInput = unknown> {
  /**
   * Path in the explorer tree.
   * - `undefined` (default): use fixture filename only
   * - `'Foo/Bar'`: exact path (fixture filename NOT appended)
   * - `'Foo/Bar/'`: prefix (fixture filename IS appended → Foo/Bar/{filename})
   * 
   * @throws Error if path contains empty segments (e.g., '/foo', 'foo//bar')
   */
  path?: string;

  /** Optional description for documentation */
  description?: string;

  /** How to isolate: 'none' (default) renders in light DOM, 'shadow-dom' for CSS isolation, 'iframe' for full isolation */
  isolation?: 'none' | 'shadow-dom' | 'iframe';

  /** Display mode: defaults to { type: 'component' } */
  displayMode?: DisplayMode;

  /** Styles to inject (into document head for 'none', into shadow root for 'shadow-dom', into iframe head for 'iframe') */
  styles?: StyleDefinition[];

  /** Background pattern for the preview canvas: 'light' (default) or 'dark' for dark transparent pattern */
  background?: 'light' | 'dark';

  /** Labels for categorization and filtering (e.g. 'animation', 'blocks-ci') */
  labels?: readonly string[];

  /** Human/AI-readable description(s) of expected visual appearance. Inherited from parent group/variants and accumulated into a string[]. */
  expectedVisualDescriptions?: string | readonly string[];

  /**
   * Zod schema describing the expected shape of `RenderContext.input`.
   *
   * Declaring it gives two things:
   *  1. **Type safety** — `render`'s `context.input` is typed as `z.infer<typeof schema>`.
   *  2. **Tooling** — the framework converts the schema to JSON Schema at define time so the
   *     CLI/MCP/explorer UI can validate, autocomplete, or render input-editing controls.
   *
   * The schema must describe an object (`z.object({...})`) — `input` is always a JSON object
   * (or `undefined`). Property-level `.default(...)` values are surfaced to tooling and used
   * to populate omitted keys before `render` runs.
   *
   * @example
   * ```ts
   * inputSchema: z.object({
   *   theme: z.enum(['light', 'dark']).default('light'),
   *   count: z.number().int().default(1),
   * })
   * ```
   */
  inputSchema?: z.ZodType<TInput>;

  /** Controls how selected input properties are presented in the Explorer UI. */
  inputControls?: {
    readonly [TKey in Extract<keyof TInput, string>]?: FixtureInputControlOptions;
  };

  /** Custom debug panels contributed by this fixture. */
  debugPanels?: readonly DebugPanelDefinition<unknown, unknown>[];

  /**
   * Render the component into the container.
   * 
   * @param container - The DOM element to render into
   * @param context - Render context containing input and abort signal
   * @returns Optional RenderResult, or a Promise that resolves to one
   */
  render: (container: HTMLElement, context: RenderContext<TInput>) => RenderReturn;
}

/** @deprecated Use DefineFixtureOptions instead */
export type DefineComponentOptions = DefineFixtureOptions;

// ============================================================================
// Fixture export types (opaque to the user, consumed by fixtureApiConsumer)
// ============================================================================

/**
 * A single fixture export created by defineFixture().
 */
export interface SingleFixtureExport {
  readonly [singleFixtureBrand]: true;
  readonly _options: DefineFixtureOptions;
  readonly _path?: string;
  /** JSON Schema derived from `_options.inputSchema` at define time (cross-version safe). */
  readonly _inputSchemaJson?: IJsonSchema;
}

/**
 * Group entry: either a single fixture, a nested group, or variants.
 */
export type FixtureGroupEntry = SingleFixtureExport | FixtureGroupExport | FixtureVariantsExport;

/**
 * A fixture group export created by defineFixtureGroup().
 */
export interface FixtureGroupExport {
  readonly [fixtureGroupBrand]: true;
  readonly _entries: { [key: string]: FixtureGroupEntry };
  readonly _path?: string;
  readonly _labels?: readonly string[];
  readonly _expectedVisualDescriptions?: string | readonly string[];
  /** JSON Schema derived from the group's `inputSchema`; merged into every descendant fixture. */
  readonly _inputSchemaJson?: IJsonSchema;
}

/**
 * A fixture variants export created by defineFixtureVariants().
 */
export interface FixtureVariantsExport {
  readonly [fixtureVariantsBrand]: true;
  readonly _variants: { [key: string]: SingleFixtureExport };
  readonly _path?: string;
  readonly _labels?: readonly string[];
  readonly _expectedVisualDescriptions?: string | readonly string[];
  /** JSON Schema derived from the variants group's `inputSchema`; merged into every variant. */
  readonly _inputSchemaJson?: IJsonSchema;
}

/**
 * Fixture export type - a single fixture, a group, or variants.
 */
export type FixtureExport = SingleFixtureExport | FixtureGroupExport | FixtureVariantsExport;

/**
 * Input for defineFixtureGroup.
 */
export type FixtureGroupInput = { [key: string]: FixtureGroupEntry };

/**
 * Options for defineFixtureGroup with optional path.
 */
export interface DefineFixtureGroupOptions {
  /**
   * Path in the explorer tree.
   * - `undefined` (default): use fixture filename only
   * - `'Foo/Bar'`: exact path (fixture filename NOT appended)
   * - `'Foo/Bar/'`: prefix (fixture filename IS appended → Foo/Bar/{filename})
   */
  path?: string;

  /** Labels for categorization and filtering (e.g. 'animation', 'blocks-ci') */
  labels?: readonly string[];

  /** Human/AI-readable description(s) of expected visual appearance. Inherited by nested fixtures. */
  expectedVisualDescriptions?: string | readonly string[];

  /**
   * Zod schema describing `input` shared by every fixture in this group. It is converted to
   * JSON Schema at define time and merged into each descendant fixture's own schema (the
   * descendant's properties win on conflict). Use it to declare common input — e.g. a `theme`
   * switch — once for a whole group instead of repeating it on each fixture.
   */
  inputSchema?: z.ZodType;
}

/**
 * Input for defineFixtureVariants (only single fixtures, no nesting).
 */
export type FixtureVariantsInput = { [key: string]: SingleFixtureExport };

/**
 * Options for defineFixtureVariants with optional path.
 */
export interface DefineFixtureVariantsOptions {
  /**
   * Path in the explorer tree.
   * - `undefined` (default): use fixture filename only  
   * - `'Foo/Bar'`: exact path (fixture filename NOT appended)
   * - `'Foo/Bar/'`: prefix (fixture filename IS appended → Foo/Bar/{filename})
   */
  path?: string;

  /** Labels for categorization and filtering (e.g. 'animation', 'blocks-ci') */
  labels?: readonly string[];

  /** Human/AI-readable description(s) of expected visual appearance. Inherited by nested fixtures. */
  expectedVisualDescriptions?: string | readonly string[];

  /**
   * Zod schema describing `input` shared by every variant in this group. Converted to JSON
   * Schema at define time and merged into each variant's own schema (the variant's properties
   * win on conflict).
   */
  inputSchema?: z.ZodType;
}

// ============================================================================
// Define fixture functions
// ============================================================================

/**
 * Converts a zod schema to the JSON Schema form surfaced to tooling.
 * Runs at define time (in the project's runtime) so only plain JSON crosses the
 * version boundary to the viewer. Returns `undefined` when no schema is given.
 */
function toInputJsonSchema(schema: z.ZodType | undefined): IJsonSchema | undefined {
  if (!schema) { return undefined; }
  return z.toJSONSchema(schema, { unrepresentable: 'any' }) as IJsonSchema;
}

/**
 * Defines a single fixture.
 * 
 * @example
 * ```ts
 * // Simple - no cleanup needed
 * export default defineFixture({
 *   render: (container) => {
 *     container.innerHTML = `<button>Click me</button>`;
 *   },
 * });
 * 
 * // Typed, parameterizable input via a zod schema
 * export default defineFixture({
 *   inputSchema: z.object({ label: z.string().default('Click me') }),
 *   render: (container, { input }) => {
 *     const root = createRoot(container);
 *     root.render(<Button label={input.label} />);
 *     return { dispose: () => root.unmount() };
 *   },
 * });
 * 
 * // Async render
 * export default defineFixture({
 *   inputSchema: z.object({ url: z.string() }),
 *   render: async (container, { input, signal }) => {
 *     const data = await fetch(input.url, { signal });
 *     container.innerHTML = await data.text();
 *     return { dispose: () => { container.innerHTML = ''; } };
 *   },
 * });
 * ```
 */
export function defineFixture<TInput = unknown>(options: DefineFixtureOptions<TInput>): SingleFixtureExport {
  return {
    [singleFixtureBrand]: true,
    _options: options as unknown as DefineFixtureOptions,
    _path: options.path,
    _inputSchemaJson: toInputJsonSchema(options.inputSchema as z.ZodType | undefined),
  };
}

export function defineDebugPanel<TState, TAction = never>(
  options: DefineDebugPanelOptions<TState, TAction>,
): DebugPanelDefinition<TState, TAction> {
  return {
    id: options.id,
    title: options.title,
    placement: options.placement,
    _render: (container, sendAction) => {
      const view = options.render(container, {
        sendAction: (action) => sendAction(action),
      });
      return {
        update: (state) => view.update(state as TState),
        dispose: () => view.dispose(),
      };
    },
  };
}

export function interactiveOutput<T>(options: {
  readonly getSnapshot: () => T;
  readonly activate: DebugPanelActivation<T, T>;
}): InteractiveOutput<T> {
  return {
    [interactiveOutputBrand]: true,
    getSnapshot: options.getSnapshot,
    activate: options.activate,
  };
}

export function isInteractiveOutput(value: unknown): value is InteractiveOutput<unknown> {
  return typeof value === 'object'
    && value !== null
    && interactiveOutputBrand in value
    && (value as Record<symbol, unknown>)[interactiveOutputBrand] === true;
}

/**
 * Defines a group of fixtures with support for nesting.
 * 
 * @example
 * ```ts
 * export default defineFixtureGroup({
 *   Primary: defineFixture({
 *     render: (container) => { ... },
 *   }),
 *   Variants: defineFixtureGroup({
 *     Small: defineFixture({ ... }),
 *     Large: defineFixture({ ... }),
 *   }),
 * });
 * ```
 */
export function defineFixtureGroup(entries: FixtureGroupInput): FixtureGroupExport;
export function defineFixtureGroup(options: DefineFixtureGroupOptions, entries: FixtureGroupInput): FixtureGroupExport;
export function defineFixtureGroup(optionsOrEntries: DefineFixtureGroupOptions | FixtureGroupInput, maybeEntries?: FixtureGroupInput): FixtureGroupExport {
  if (maybeEntries !== undefined) {
    const opts = optionsOrEntries as DefineFixtureGroupOptions;
    return {
      [fixtureGroupBrand]: true,
      _entries: maybeEntries,
      _path: opts.path,
      _labels: opts.labels,
      _expectedVisualDescriptions: opts.expectedVisualDescriptions,
      _inputSchemaJson: toInputJsonSchema(opts.inputSchema),
    };
  }
  return {
    [fixtureGroupBrand]: true,
    _entries: optionsOrEntries as FixtureGroupInput,
  };
}

/**
 * Defines a group of fixture variants (no nesting allowed).
 * Variants are rendered horizontally by default and have a distinct icon in the tree.
 * 
 * @example
 * ```ts
 * export default defineFixtureGroup({
 *   Button: defineFixtureVariants({
 *     Small: defineFixture({ ... }),
 *     Medium: defineFixture({ ... }),
 *     Large: defineFixture({ ... }),
 *   }),
 * });
 * ```
 */
export function defineFixtureVariants(variants: FixtureVariantsInput): FixtureVariantsExport;
export function defineFixtureVariants(options: DefineFixtureVariantsOptions, variants: FixtureVariantsInput): FixtureVariantsExport;
export function defineFixtureVariants(optionsOrVariants: DefineFixtureVariantsOptions | FixtureVariantsInput, maybeVariants?: FixtureVariantsInput): FixtureVariantsExport {
  if (maybeVariants !== undefined) {
    const opts = optionsOrVariants as DefineFixtureVariantsOptions;
    return {
      [fixtureVariantsBrand]: true,
      _variants: maybeVariants,
      _path: opts.path,
      _labels: opts.labels,
      _expectedVisualDescriptions: opts.expectedVisualDescriptions,
      _inputSchemaJson: toInputJsonSchema(opts.inputSchema),
    };
  }
  return {
    [fixtureVariantsBrand]: true,
    _variants: optionsOrVariants as FixtureVariantsInput,
  };
}

// ============================================================================
// Render helpers
// ============================================================================

/** Already-resolved promise, reused for efficiency */
const resolvedPromise = Promise.resolve();

/**
 * Helper for synchronous renders.
 * Executes the render function immediately and wraps the cleanup in a RenderResult.
 * 
 * @param doRender - Function that renders synchronously and returns a cleanup function
 * @returns A RenderResult with an already-resolved ready promise
 * 
 * @example
 * ```ts
 * render: (container, { input }) => syncRender(() => {
 *   const el = document.createElement('button');
 *   el.textContent = input.label;
 *   container.appendChild(el);
 *   return () => el.remove();
 * })
 * ```
 */
export function syncRender(doRender: () => (() => void) | IDisposable | void): RenderResult {
  const cleanup = doRender();
  return {
    ready: resolvedPromise,
    dispose: () => {
      if (typeof cleanup === 'function') {
        cleanup();
      } else if (cleanup && typeof cleanup.dispose === 'function') {
        cleanup.dispose();
      }
    },
  };
}

/**
 * Helper for asynchronous renders with cancellation support.
 * 
 * @param signal - AbortSignal for cancellation
 * @param doRender - Async function that renders and returns a cleanup function.
 *                   Should check signal.aborted periodically for long operations.
 * @returns A RenderResult whose ready promise rejects with AbortError if cancelled
 * 
 * @example
 * ```ts
 * render: (container, { input, signal }) => asyncRender(signal, async () => {
 *   const data = await fetchData(input.url, { signal });
 *   if (signal.aborted) return;
 *   container.innerHTML = data;
 *   return () => { container.innerHTML = ''; };
 * })
 * ```
 */
export function asyncRender(
  signal: AbortSignal,
  doRender: () => Promise<(() => void) | IDisposable | void>
): RenderResult {
  let cleanup: (() => void) | IDisposable | void;
  let disposed = false;

  function isAborted(): boolean {
    return signal.aborted;
  }

  const ready = (async () => {
    if (isAborted()) {
      throw new DOMException('Render aborted', 'AbortError');
    }
    cleanup = await doRender();
    if (isAborted() || disposed) {
      // Cleanup immediately if aborted/disposed during render
      doCleanup();
      if (isAborted()) {
        throw new DOMException('Render aborted', 'AbortError');
      }
    }
  })();

  function doCleanup(): void {
    if (typeof cleanup === 'function') {
      cleanup();
    } else if (cleanup && typeof cleanup.dispose === 'function') {
      cleanup.dispose();
    }
    cleanup = undefined;
  }

  return {
    ready,
    dispose: () => {
      disposed = true;
      doCleanup();
    },
  };
}
